/*
 * count_composites.c -- exhaustive counts in Exclusion Arithmetic,
 * the semiring S = N_0[x]/<2 ~ 1+x> on binary normal forms (x -> 2).
 *
 *   count_composites N      C(n), n = 1..N: number of odd n-bit composites
 *   count_composites N A    D_A(n), n = 1..N: number of odd n-bit multiples
 *                           of the odd element A
 *
 * Output: one "n value" pair per line on stdout; diagnostics on stderr.
 *
 * Method.  A sieve over a bitmap of the odd integers below 2^N.  For a fixed
 * factor c, the products b (x) c over all odd b are generated by a depth-first
 * walk over the bits of b, using distributivity:
 *     (b + x^k) (x) c = (b (x) c) [+] (c << k)      (k above the top bit of b)
 * so every product costs one exclusion addition.  Lengths are superadditive
 * (len(b (x) c) >= len b + len c - 1) and [+] never clears a bit, so a
 * partial product that outgrows N bits is abandoned without loss.  Every
 * composite is b (x) c with len b <= len c, which halves the walk.
 *
 * Arithmetic safety.  eadd() refuses (returns 0) as soon as a result would
 * reach bit N, so no intermediate value ever exceeds 2^N <= 2^62; nothing is
 * silently truncated.  At start-up eadd() is checked exhaustively against the
 * defining Lindley recursion  carry' = max(carry + a_k + b_k - 1, 0).
 *
 * Build:  cc -std=c11 -O3 [-fopenmp] count_composites.c -o count_composites
 * Memory: 2^(N-4) bytes (128 MiB for N = 31).
 */
#include <inttypes.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef uint64_t u64;

static int N;                  /* maximal bit length */
static u64 LIMIT;              /* 2^N */
static _Atomic u64 *bitmap;    /* bit (v >> 1) is set iff odd v was produced */

/* a [+] b for a, b < 2^N; returns 0 when the result has more than N bits.
 * The result is a | b with every unit of a & b moved up to the nearest
 * still-free position above it (the Lindley carry, one unit at a time). */
static inline u64 eadd(u64 a, u64 b)
{
    u64 r = a | b, d = a & b;
    while (d) {
        u64 t = d & (0 - d);          /* lowest pending unit */
        u64 m = r | t | (t - 1);      /* r with everything up to t filled */
        u64 z = (m + 1) & ~m;         /* lowest free position above t */
        if (z >= LIMIT)
            return 0;
        r |= z;
        d ^= t;
    }
    return r;
}

/* The definition, bit by bit; used only by selftest(). */
static u64 eadd_lindley(u64 a, u64 b)
{
    u64 r = 0;
    int carry = 0;
    for (int k = 0; a >> k || b >> k || carry; k++) {
        int t = (int)(a >> k & 1) + (int)(b >> k & 1) + carry;
        if (t > 0)
            r |= (u64)1 << k;
        carry = t > 0 ? t - 1 : 0;
    }
    return r;
}

static void selftest(void)
{
    u64 saved = LIMIT;
    LIMIT = (u64)1 << 62;
    for (u64 a = 0; a < 1024; a++)
        for (u64 b = a; b < 1024; b++)
            if (eadd(a, b) != eadd_lindley(a, b)) {
                fprintf(stderr, "selftest failed at %" PRIu64 " [+] %" PRIu64 "\n", a, b);
                exit(2);
            }
    u64 s = 88172645463325252u;       /* xorshift64, 30-bit operands */
    for (int i = 0; i < 2000000; i++) {
        s ^= s << 13; s ^= s >> 7; s ^= s << 17;
        u64 a = s & 0x3fffffff, b = s >> 34;
        if (eadd(a, b) != eadd_lindley(a, b)) {
            fprintf(stderr, "selftest failed at %" PRIu64 " [+] %" PRIu64 "\n", a, b);
            exit(2);
        }
    }
    LIMIT = saved;
}

static inline void mark(u64 v)
{
    u64 i = v >> 1, bit = (u64)1 << (i & 63);
    if (!(atomic_load_explicit(&bitmap[i >> 6], memory_order_relaxed) & bit))
        atomic_fetch_or_explicit(&bitmap[i >> 6], bit, memory_order_relaxed);
}

/* p = b (x) c for some odd b with top bit below k; extend b by bits k..kmax. */
static void walk(u64 c, u64 p, int k, int kmax)
{
    for (; k <= kmax; k++) {
        u64 q = eadd(p, c << k);
        if (q) {
            mark(q);
            walk(c, q, k + 1, kmax);
        }
    }
}

static int bitlen(u64 v)
{
    int n = 0;
    while (v) { n++; v >>= 1; }
    return n;
}

int main(int argc, char **argv)
{
    u64 a = 0;
    if (argc < 2 || argc > 3 || (N = atoi(argv[1])) < 2 || N > 40
        || (argc == 3 && (!((a = strtoull(argv[2], 0, 10)) & 1) || bitlen(a) > N))) {
        fprintf(stderr, "usage: %s N [A]    (2 <= N <= 40, A odd, A < 2^N)\n", argv[0]);
        return 1;
    }
    LIMIT = (u64)1 << N;
    selftest();
    size_t words = (size_t)1 << (N > 7 ? N - 7 : 0);
    bitmap = calloc(words, sizeof *bitmap);
    if (!bitmap) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    if (a) {                            /* all odd multiples of a */
        mark(a);
        walk(a, a, 1, N - bitlen(a));
    } else {                            /* all b (x) c, 2 <= len b <= len c */
        for (int lc = 2; lc < N; lc++) {
            int kmax = lc - 1 < N - lc ? lc - 1 : N - lc;
            long long lo = (1LL << (lc - 1)) + 1, hi = 1LL << lc;
            #pragma omp parallel for schedule(dynamic, 64)
            for (long long c = lo; c < hi; c += 2)
                walk((u64)c, (u64)c, 1, kmax);
            fprintf(stderr, "len c = %d done\n", lc);
        }
    }
    for (int n = 1; n <= N; n++) {      /* odd n-bit v: v >> 1 in [2^(n-2), 2^(n-1)) */
        u64 lo = n == 1 ? 0 : (u64)1 << (n - 2), hi = (u64)1 << (n - 1), cnt = 0;
        for (u64 i = lo; i < hi; ) {
            if (!(i & 63) && i + 64 <= hi) {
                cnt += (u64)__builtin_popcountll(atomic_load(&bitmap[i >> 6]));
                i += 64;
            } else {
                cnt += atomic_load(&bitmap[i >> 6]) >> (i & 63) & 1;
                i++;
            }
        }
        printf("%d %" PRIu64 "\n", n, cnt);
    }
    return 0;
}
